def longest_run(seq: str) -> int:
    """Length of the longest stretch of one repeated character."""
    best: int = 0
    run: int = 0
    prev: str = ""
    for ch in seq:
        if ch == prev:
            run += 1
        else:
            run = 1
            prev = ch
        if run > best:
            best = run
    return best

